export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "子の刻を過ぎて、師匠は休むことにした。去りぎわに、炉の火を小さく落としていった。", ruby: [{"start":0,"end":1,"reading":"ね"},{"start":2,"end":3,"reading":"こく"},{"start":4,"end":5,"reading":"す"},{"start":8,"end":10,"reading":"ししょう"},{"start":11,"end":12,"reading":"やす"},{"start":19,"end":20,"reading":"さ"},{"start":25,"end":26,"reading":"ろ"},{"start":27,"end":28,"reading":"ひ"},{"start":29,"end":30,"reading":"ちい"},{"start":32,"end":33,"reading":"お"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "夜明け前の一壺は、お前が淹れろ。淹れたら、関まで提げていけ。", ruby: [{"start":0,"end":2,"reading":"よあ"},{"start":3,"end":4,"reading":"まえ"},{"start":5,"end":7,"reading":"ひとつぼ"},{"start":10,"end":11,"reading":"まえ"},{"start":12,"end":13,"reading":"い"},{"start":16,"end":17,"reading":"い"},{"start":21,"end":22,"reading":"せき"},{"start":24,"end":25,"reading":"さ"}], background: Background.Root_Act2_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "誰に？", ruby: [{"start":0,"end":1,"reading":"だれ"}], background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.WenBo, character: "温伯", dialogue: "まだ立っている者にだ。", ruby: [{"start":2,"end":3,"reading":"た"},{"start":7,"end":8,"reading":"もの"}], background: Background.Root_Act2_S0, portrait: Portrait.WenBo_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "部屋の戸が閉まった。雨は少し弱まり、叩きつける音から、ぶつぶつとこぼす声に変わった。", ruby: [{"start":0,"end":2,"reading":"へや"},{"start":3,"end":4,"reading":"と"},{"start":5,"end":6,"reading":"し"},{"start":10,"end":11,"reading":"あめ"},{"start":12,"end":13,"reading":"すこ"},{"start":14,"end":15,"reading":"よわ"},{"start":18,"end":19,"reading":"たた"},{"start":23,"end":24,"reading":"おと"},{"start":35,"end":36,"reading":"こえ"},{"start":37,"end":38,"reading":"か"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "杯を片づけていた小満は、窓ぎわの卓に人がひとり増えているのに気づいた。", ruby: [{"start":0,"end":1,"reading":"さかずき"},{"start":2,"end":3,"reading":"かた"},{"start":8,"end":10,"reading":"しょうまん"},{"start":12,"end":13,"reading":"まど"},{"start":16,"end":17,"reading":"たく"},{"start":18,"end":19,"reading":"ひと"},{"start":23,"end":24,"reading":"ふ"},{"start":30,"end":31,"reading":"き"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "戸を叩く音はしなかった。閂も差したままだ。", ruby: [{"start":0,"end":1,"reading":"と"},{"start":2,"end":3,"reading":"たた"},{"start":4,"end":5,"reading":"おと"},{"start":12,"end":13,"reading":"かんぬき"},{"start":14,"end":15,"reading":"さ"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）……裏の窓。留め金が壊れてもう半年、師匠はずっと直すって言ってたのに。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":7,"end":8,"reading":"うら"},{"start":9,"end":10,"reading":"まど"},{"start":11,"end":12,"reading":"と"},{"start":13,"end":14,"reading":"がね"},{"start":15,"end":16,"reading":"こわ"},{"start":20,"end":22,"reading":"はんとし"},{"start":23,"end":25,"reading":"ししょう"},{"start":29,"end":30,"reading":"なお"},{"start":33,"end":34,"reading":"い"}], background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "大きな声を出さないでくれ。泥棒じゃない。この家の者だ。", ruby: [{"start":0,"end":1,"reading":"おお"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":6,"reading":"だ"},{"start":13,"end":15,"reading":"どろぼう"},{"start":22,"end":23,"reading":"いえ"},{"start":24,"end":25,"reading":"もの"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "二階の男より、いくつか若い。ずぶ濡れの髪を無造作に後ろへかき上げ、顔にかすかな笑みを浮かべている。面白くもない冗談に、礼儀として笑ってみせるような笑みだった。", ruby: [{"start":0,"end":2,"reading":"にかい"},{"start":3,"end":4,"reading":"おとこ"},{"start":11,"end":12,"reading":"わか"},{"start":16,"end":17,"reading":"ぬ"},{"start":19,"end":20,"reading":"かみ"},{"start":21,"end":24,"reading":"むぞうさ"},{"start":25,"end":26,"reading":"うし"},{"start":30,"end":31,"reading":"あ"},{"start":33,"end":34,"reading":"かお"},{"start":39,"end":40,"reading":"え"},{"start":42,"end":43,"reading":"う"},{"start":49,"end":51,"reading":"おもしろ"},{"start":55,"end":57,"reading":"じょうだん"},{"start":59,"end":61,"reading":"れいぎ"},{"start":64,"end":65,"reading":"わら"},{"start":73,"end":74,"reading":"え"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "腰には剣が一振り。鞘はひどく古いのに、彼の身につけているどれよりもきれいだった。", ruby: [{"start":0,"end":1,"reading":"こし"},{"start":3,"end":4,"reading":"けん"},{"start":5,"end":7,"reading":"ひとふ"},{"start":9,"end":10,"reading":"さや"},{"start":14,"end":15,"reading":"ふる"},{"start":19,"end":20,"reading":"かれ"},{"start":21,"end":22,"reading":"み"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "君、師匠が新しく拾った子かい。", ruby: [{"start":0,"end":1,"reading":"きみ"},{"start":2,"end":4,"reading":"ししょう"},{"start":5,"end":6,"reading":"あたら"},{"start":8,"end":9,"reading":"ひろ"},{"start":11,"end":12,"reading":"こ"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "七年。新しくない。", ruby: [{"start":0,"end":2,"reading":"しちねん"},{"start":3,"end":4,"reading":"あたら"}], background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "俺からすれば新顔だよ。", ruby: [{"start":0,"end":1,"reading":"おれ"},{"start":6,"end":8,"reading":"しんがお"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は立ち上がって戸の枠の前に行き、「遅」の刻み傷に手を伸ばした。指の腹が、そこで少しとまった。", ruby: [{"start":0,"end":1,"reading":"かれ"},{"start":2,"end":3,"reading":"た"},{"start":4,"end":5,"reading":"あ"},{"start":8,"end":9,"reading":"と"},{"start":10,"end":11,"reading":"わく"},{"start":12,"end":13,"reading":"まえ"},{"start":14,"end":15,"reading":"い"},{"start":18,"end":19,"reading":"ち"},{"start":21,"end":22,"reading":"きざ"},{"start":23,"end":24,"reading":"きず"},{"start":25,"end":26,"reading":"て"},{"start":27,"end":28,"reading":"の"},{"start":32,"end":33,"reading":"ゆび"},{"start":34,"end":35,"reading":"はら"},{"start":40,"end":41,"reading":"すこ"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "へえ。俺、あの頃こんなに小さかったのか。", ruby: [{"start":3,"end":4,"reading":"おれ"},{"start":7,"end":8,"reading":"ころ"},{"start":12,"end":13,"reading":"ちい"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）私のより、頭ひとつ高いくせに。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":6,"reading":"わたし"},{"start":10,"end":11,"reading":"あたま"},{"start":14,"end":15,"reading":"たか"}], background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "茶はあるかい。", ruby: [{"start":0,"end":1,"reading":"ちゃ"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "蟹眼、魚眼、急須を温め、茶葉を入れる。一煎目を捨てるとき、背後で彼が小さく笑うのが聞こえた。", ruby: [{"start":0,"end":2,"reading":"かいがん"},{"start":3,"end":5,"reading":"ぎょがん"},{"start":6,"end":8,"reading":"きゅうす"},{"start":9,"end":10,"reading":"あたた"},{"start":12,"end":14,"reading":"ちゃば"},{"start":15,"end":16,"reading":"い"},{"start":19,"end":22,"reading":"いっせんめ"},{"start":23,"end":24,"reading":"す"},{"start":29,"end":31,"reading":"はいご"},{"start":32,"end":33,"reading":"かれ"},{"start":34,"end":35,"reading":"ちい"},{"start":37,"end":38,"reading":"わら"},{"start":41,"end":42,"reading":"き"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "まだ捨ててるのか。師匠の悪い癖だ、十年たっても直らない。", ruby: [{"start":2,"end":3,"reading":"す"},{"start":9,"end":11,"reading":"ししょう"},{"start":12,"end":13,"reading":"わる"},{"start":14,"end":15,"reading":"くせ"},{"start":17,"end":19,"reading":"じゅうねん"},{"start":23,"end":24,"reading":"なお"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "癖じゃない。一煎目は、後に続くもののために、先に苦い思いをするの。", ruby: [{"start":0,"end":1,"reading":"くせ"},{"start":6,"end":9,"reading":"いっせんめ"},{"start":11,"end":12,"reading":"あと"},{"start":13,"end":14,"reading":"つづ"},{"start":22,"end":23,"reading":"さき"},{"start":24,"end":25,"reading":"にが"},{"start":26,"end":27,"reading":"おも"}], background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "……まだそれを言ってるのか、あの人。", ruby: [{"start":7,"end":8,"reading":"い"},{"start":16,"end":17,"reading":"ひと"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は茶を受け取ると一息に飲みほし、熱さに顔をしかめて、杯を押し戻した。", ruby: [{"start":0,"end":1,"reading":"かれ"},{"start":2,"end":3,"reading":"ちゃ"},{"start":4,"end":5,"reading":"う"},{"start":6,"end":7,"reading":"と"},{"start":9,"end":11,"reading":"ひといき"},{"start":12,"end":13,"reading":"の"},{"start":17,"end":18,"reading":"あつ"},{"start":20,"end":21,"reading":"かお"},{"start":27,"end":28,"reading":"さかずき"},{"start":29,"end":30,"reading":"お"},{"start":31,"end":32,"reading":"もど"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "二階のあの人、何を背負ってた？", ruby: [{"start":0,"end":2,"reading":"にかい"},{"start":5,"end":6,"reading":"ひと"},{"start":7,"end":8,"reading":"なに"},{"start":9,"end":11,"reading":"せお"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "剣。油紙に包んで。", ruby: [{"start":0,"end":1,"reading":"けん"},{"start":2,"end":4,"reading":"あぶらがみ"},{"start":5,"end":6,"reading":"つつ"}], background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "黒い鞘で、鞘尻が欠けてる。", ruby: [{"start":0,"end":1,"reading":"くろ"},{"start":2,"end":3,"reading":"さや"},{"start":5,"end":7,"reading":"さやじり"},{"start":8,"end":9,"reading":"か"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "見てない。", ruby: [{"start":0,"end":1,"reading":"み"}], background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "それは俺の剣だ。俺の腰にあるこれが、兄さんの。十年、互いの剣を背負ってきたんだ。笑えるだろ。", ruby: [{"start":3,"end":4,"reading":"おれ"},{"start":5,"end":6,"reading":"けん"},{"start":8,"end":9,"reading":"おれ"},{"start":10,"end":11,"reading":"こし"},{"start":18,"end":19,"reading":"にい"},{"start":23,"end":25,"reading":"じゅうねん"},{"start":26,"end":27,"reading":"たが"},{"start":29,"end":30,"reading":"けん"},{"start":31,"end":33,"reading":"せお"},{"start":40,"end":41,"reading":"わら"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）笑えない。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":6,"reading":"わら"}], background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼はそれを見てとった。笑みが少し薄れ、それでも消えきりはしなかった。", ruby: [{"start":0,"end":1,"reading":"かれ"},{"start":5,"end":6,"reading":"み"},{"start":11,"end":12,"reading":"え"},{"start":14,"end":15,"reading":"すこ"},{"start":16,"end":17,"reading":"うす"},{"start":23,"end":24,"reading":"き"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "師匠は寝た。兄さんも寝た。この家で起きてるのは君だけだ。", ruby: [{"start":0,"end":2,"reading":"ししょう"},{"start":3,"end":4,"reading":"ね"},{"start":6,"end":7,"reading":"にい"},{"start":10,"end":11,"reading":"ね"},{"start":15,"end":16,"reading":"いえ"},{"start":17,"end":18,"reading":"お"},{"start":23,"end":24,"reading":"きみ"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "ひとつ話をしよう。君は数に入らないから、話せる。", ruby: [{"start":3,"end":4,"reading":"はなし"},{"start":9,"end":10,"reading":"きみ"},{"start":11,"end":12,"reading":"かず"},{"start":13,"end":14,"reading":"はい"},{"start":20,"end":21,"reading":"はな"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "数に入らないって、どういうこと。", ruby: [{"start":0,"end":1,"reading":"かず"},{"start":2,"end":3,"reading":"はい"}], background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "話しても、話さなかったのと同じってことさ。一煎目みたいにね。", ruby: [{"start":0,"end":1,"reading":"はな"},{"start":5,"end":6,"reading":"はな"},{"start":13,"end":14,"reading":"おな"},{"start":21,"end":24,"reading":"いっせんめ"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）この人、ほんとに嫌な言い方をする。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":7,"end":8,"reading":"ひと"},{"start":13,"end":14,"reading":"いや"},{"start":15,"end":16,"reading":"い"},{"start":17,"end":18,"reading":"かた"}], background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "それでも、小満は離れなかった。腰を下ろした。", ruby: [{"start":5,"end":7,"reading":"しょうまん"},{"start":8,"end":9,"reading":"はな"},{"start":15,"end":16,"reading":"こし"},{"start":17,"end":18,"reading":"お"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "十年前のあの晩、兄さんは関で白鷺門の門主の息子と剣を交えた。相手が負けると、兄さんは剣を納めてそのまま去った。振り返りもしなかった。", ruby: [{"start":0,"end":3,"reading":"じゅうねんまえ"},{"start":6,"end":7,"reading":"ばん"},{"start":8,"end":9,"reading":"にい"},{"start":12,"end":13,"reading":"せき"},{"start":14,"end":17,"reading":"はくろもん"},{"start":18,"end":20,"reading":"もんしゅ"},{"start":21,"end":23,"reading":"むすこ"},{"start":24,"end":25,"reading":"けん"},{"start":26,"end":27,"reading":"まじ"},{"start":30,"end":32,"reading":"あいて"},{"start":33,"end":34,"reading":"ま"},{"start":38,"end":39,"reading":"にい"},{"start":42,"end":43,"reading":"けん"},{"start":44,"end":45,"reading":"おさ"},{"start":51,"end":52,"reading":"さ"},{"start":55,"end":56,"reading":"ふ"},{"start":57,"end":58,"reading":"かえ"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "俺は後ろで見ていた。そいつは立ち上がって、また座りこんで、それきり動かなくなった。", ruby: [{"start":0,"end":1,"reading":"おれ"},{"start":2,"end":3,"reading":"うし"},{"start":5,"end":6,"reading":"み"},{"start":14,"end":15,"reading":"た"},{"start":16,"end":17,"reading":"あ"},{"start":23,"end":24,"reading":"すわ"},{"start":33,"end":34,"reading":"うご"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "駆け寄ったときには、もう血が石の隙間に染みこんでいた。兄さんのあの一突きは、深すぎたんだ。本人は知らない。あの人は昔から、自分の剣がどれほど重いか知らないんだよ。", ruby: [{"start":0,"end":1,"reading":"か"},{"start":2,"end":3,"reading":"よ"},{"start":12,"end":13,"reading":"ち"},{"start":14,"end":15,"reading":"いし"},{"start":16,"end":18,"reading":"すきま"},{"start":19,"end":20,"reading":"し"},{"start":27,"end":28,"reading":"にい"},{"start":33,"end":35,"reading":"ひとつ"},{"start":38,"end":39,"reading":"ふか"},{"start":45,"end":47,"reading":"ほんにん"},{"start":48,"end":49,"reading":"し"},{"start":55,"end":56,"reading":"ひと"},{"start":57,"end":58,"reading":"むかし"},{"start":61,"end":63,"reading":"じぶん"},{"start":64,"end":65,"reading":"けん"},{"start":70,"end":71,"reading":"おも"},{"start":73,"end":74,"reading":"し"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "軒から、しずくがひとつ、またひとつ落ちる。数えられるほどの間をおいて。", ruby: [{"start":0,"end":1,"reading":"のき"},{"start":17,"end":18,"reading":"お"},{"start":21,"end":22,"reading":"かぞ"},{"start":29,"end":30,"reading":"ま"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "白鷺門の連中は傷を読む。あの幅なら、ひと目でどの剣かわかる。", ruby: [{"start":0,"end":3,"reading":"はくろもん"},{"start":4,"end":6,"reading":"れんちゅう"},{"start":7,"end":8,"reading":"きず"},{"start":9,"end":10,"reading":"よ"},{"start":14,"end":15,"reading":"はば"},{"start":20,"end":21,"reading":"め"},{"start":24,"end":25,"reading":"けん"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "あの年、兄さんは二十で、師匠はこの茶館を兄さんに譲ると言ったばかりだった。俺は十七で、何も持っていなかった。", ruby: [{"start":2,"end":3,"reading":"とし"},{"start":4,"end":5,"reading":"にい"},{"start":8,"end":10,"reading":"はたち"},{"start":12,"end":14,"reading":"ししょう"},{"start":17,"end":19,"reading":"ちゃかん"},{"start":20,"end":21,"reading":"にい"},{"start":24,"end":25,"reading":"ゆず"},{"start":27,"end":28,"reading":"い"},{"start":37,"end":38,"reading":"おれ"},{"start":39,"end":41,"reading":"じゅうしち"},{"start":43,"end":44,"reading":"なに"},{"start":45,"end":46,"reading":"も"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "だから俺が兄さんの剣を持ち出して、自分のを置いて、戸口にあの言葉を刻んだ。それだけさ。", ruby: [{"start":3,"end":4,"reading":"おれ"},{"start":5,"end":6,"reading":"にい"},{"start":9,"end":10,"reading":"けん"},{"start":11,"end":12,"reading":"も"},{"start":13,"end":14,"reading":"だ"},{"start":17,"end":19,"reading":"じぶん"},{"start":21,"end":22,"reading":"お"},{"start":25,"end":27,"reading":"とぐち"},{"start":30,"end":32,"reading":"ことば"},{"start":33,"end":34,"reading":"きざ"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "……それだけ？", background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "それだけ。白鷺門には十年追われたよ。まあ公平さ、俺のほうが足は速い。", ruby: [{"start":5,"end":8,"reading":"はくろもん"},{"start":10,"end":12,"reading":"じゅうねん"},{"start":12,"end":13,"reading":"お"},{"start":20,"end":22,"reading":"こうへい"},{"start":24,"end":25,"reading":"おれ"},{"start":29,"end":30,"reading":"あし"},{"start":31,"end":32,"reading":"はや"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "じゃあ、夜明けには――", ruby: [{"start":4,"end":6,"reading":"よあ"}], background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "夜明けには、兄さんが勝つ。", ruby: [{"start":0,"end":2,"reading":"よあ"},{"start":6,"end":7,"reading":"にい"},{"start":10,"end":11,"reading":"か"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "明日は晴れるよ、とでも言うような、軽い口ぶりだった。", ruby: [{"start":0,"end":2,"reading":"あした"},{"start":3,"end":4,"reading":"は"},{"start":11,"end":12,"reading":"い"},{"start":17,"end":18,"reading":"かる"},{"start":19,"end":20,"reading":"くち"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "白鷺門が欲しいのは、死んだ下手人だ。兄さんが俺を斬れば、あの件は兄さんの手で片がつく。向こうは温家に借りまでできる。兄さんはここへ戻って、この茶館を継げばいい。きれいな身のままでね。", ruby: [{"start":0,"end":3,"reading":"はくろもん"},{"start":4,"end":5,"reading":"ほ"},{"start":10,"end":11,"reading":"し"},{"start":13,"end":16,"reading":"げしゅにん"},{"start":18,"end":19,"reading":"にい"},{"start":22,"end":23,"reading":"おれ"},{"start":24,"end":25,"reading":"き"},{"start":30,"end":31,"reading":"けん"},{"start":32,"end":33,"reading":"にい"},{"start":36,"end":37,"reading":"て"},{"start":38,"end":39,"reading":"かた"},{"start":43,"end":44,"reading":"む"},{"start":47,"end":49,"reading":"おんけ"},{"start":50,"end":51,"reading":"か"},{"start":58,"end":59,"reading":"にい"},{"start":65,"end":66,"reading":"もど"},{"start":71,"end":73,"reading":"ちゃかん"},{"start":74,"end":75,"reading":"つ"},{"start":84,"end":85,"reading":"み"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "師匠も年だ。誰かがここで湯を沸かさなきゃならない。", ruby: [{"start":0,"end":2,"reading":"ししょう"},{"start":3,"end":4,"reading":"とし"},{"start":6,"end":7,"reading":"だれ"},{"start":12,"end":13,"reading":"ゆ"},{"start":14,"end":15,"reading":"わ"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "本人に話せばいいのに。", ruby: [{"start":0,"end":2,"reading":"ほんにん"},{"start":3,"end":4,"reading":"はな"}], background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "話したら、兄さんが背負うことになる。あの人は他人の過ちまで自分で抱えこむ人だ。まして本当に自分のものなら、なおさらさ。", ruby: [{"start":0,"end":1,"reading":"はな"},{"start":5,"end":6,"reading":"にい"},{"start":9,"end":11,"reading":"せお"},{"start":20,"end":21,"reading":"ひと"},{"start":22,"end":24,"reading":"たにん"},{"start":25,"end":26,"reading":"あやま"},{"start":29,"end":31,"reading":"じぶん"},{"start":32,"end":33,"reading":"かか"},{"start":36,"end":37,"reading":"ひと"},{"start":42,"end":44,"reading":"ほんとう"},{"start":45,"end":47,"reading":"じぶん"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "俺は十年背負って、もう慣れた。肩のほうが、すっかりこの形になっちまった。", ruby: [{"start":0,"end":1,"reading":"おれ"},{"start":2,"end":4,"reading":"じゅうねん"},{"start":4,"end":6,"reading":"せお"},{"start":11,"end":12,"reading":"な"},{"start":15,"end":16,"reading":"かた"},{"start":27,"end":28,"reading":"かたち"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は空の杯をくるりと一回しして、口を下にして卓に伏せた。", ruby: [{"start":0,"end":1,"reading":"かれ"},{"start":2,"end":3,"reading":"から"},{"start":4,"end":5,"reading":"さかずき"},{"start":10,"end":12,"reading":"ひとまわ"},{"start":16,"end":17,"reading":"くち"},{"start":18,"end":19,"reading":"した"},{"start":22,"end":23,"reading":"たく"},{"start":24,"end":25,"reading":"ふ"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "君は、茶を注いでくれればそれでいい。", ruby: [{"start":0,"end":1,"reading":"きみ"},{"start":3,"end":4,"reading":"ちゃ"},{"start":5,"end":6,"reading":"そそ"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "それから、夜明けに一煎目を捨てるとき、口をへの字にしないでくれよ。", ruby: [{"start":5,"end":7,"reading":"よあ"},{"start":9,"end":12,"reading":"いっせんめ"},{"start":13,"end":14,"reading":"す"},{"start":19,"end":20,"reading":"くち"},{"start":23,"end":24,"reading":"じ"}], background: Background.Root_Act2_S0, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は壁にもたれて目を閉じた。本当に眠れるとでもいうように。", ruby: [{"start":0,"end":1,"reading":"かれ"},{"start":2,"end":3,"reading":"かべ"},{"start":8,"end":9,"reading":"め"},{"start":10,"end":11,"reading":"と"},{"start":14,"end":16,"reading":"ほんとう"},{"start":17,"end":18,"reading":"ねむ"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）一煎目。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":8,"reading":"いっせんめ"}], background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）あれは、この人のことだったんだ。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":11,"end":12,"reading":"ひと"}], background: Background.Root_Act2_S0, portrait: Portrait.XiaoMan_Base },
];
